def get_a_n(n_max):
    a = [0] * (n_max + 1)
    a[1] = 10
    for n in range(1, n_max):
        a[n+1] = 6 * a[n] - 2**(n+2) - 3**(n+1) + 5
    return a[1:]

a_vals = get_a_n(20)
for i, val in enumerate(a_vals):
    print(f"a_{i+1} = {val}")

def check_prime(p, n_max=1000):
    for n in range(1, n_max):
        if (pow(6, n, p) + pow(3, n, p) + pow(2, n, p) - 1) % p == 0:
            return True, n
    return False, None

primes_to_test = [p for p in range(2, 1000) if all(p % i != 0 for i in range(2, int(p**0.5)+1))]
for p in primes_to_test:
    found, n = check_prime(p)
    if not found:
        print(f"Prime {p} does not divide any a_n for n < 1000")

def check_prime(p, n_max=5000):
    for n in range(1, n_max):
        if (pow(6, n, p) + pow(3, n, p) + pow(2, n, p) - 1) % p == 0:
            return True, n
    return False, None

primes_to_test = [p for p in range(2, 2000) if all(p % i != 0 for i in range(2, int(p**0.5)+1))]
no_n_found = []
for p in primes_to_test:
    found, n = check_prime(p)
    if not found:
        no_n_found.append(p)

print(f"Primes with no n < 5000: {no_n_found}")
